head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _3 : @param columnInfo 의 MultiLine caveat 전용 샘플.
//     한 데이터 레코드를 2개의 Line(TR)으로 표시(MultiLine).
//       Line1 : sales(text/number, displayFormat, idx0) | detail(link, idx1) | grade(select, nodeset itemset, idx2)
//       Line2 : memo(textarea, colspan2, idx3) | region(text, idx4)
//     · Row 가 MultiLine(레코드당 2 Line)이어도 컬럼 인덱스는 Line 을 넘어 이어지는 고유값(0,1,2,3,4)을 가짐.
//       → Line1 의 컬럼(idx0/1/2)과 Line2 의 컬럼(idx3/4)이 서로 다른 고유 인덱스로
//         각각 setCustomFormatter 대상이 되어, 지정한 인덱스의 Column 표시값만 포매터로 변형됨.
//     · 모든 대상 컬럼은 allow-list(text/link/select/textarea) 이므로 setCustomFormatter 가 동작한다.
scwin.tData = {
    "description" : "[gridView > M > setCustomFormatter]<br/>Body Column 정보를 사용하여 특정 Column 의 customFormatter 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정되고 MultiLine 인 경우에도 모든 Column 이 고유의 인덱스를 가집니다."
    ]
}



// ★ formatter(사용자 함수) 1 : formattedData(포맷 적용 데이터) + 고유 columnIndex 표기
//  MultiLine 이어도 각 Column 이 고유 인덱스를 가지므로 columnIndex 로 Line1/Line2 대상을 구분할 수 있음
scwin.fmtMark = function (data, formattedData, rowIndex, columnIndex) {
    return "◆" + formattedData + " (idx" + columnIndex + ")";
};

// ★ formatter(사용자 함수) 2 : 파라미터 4종(data/formattedData/rowIndex/columnIndex) + this=GridView 검증용
//  this.getRowCount() 는 GridView 메소드 -> this 가 GridView 컴포넌트여야만 정상 반환됨
scwin.fmtFull = function (data, formattedData, rowIndex, columnIndex) {
    return "[r" + rowIndex + " c" + columnIndex + "] d=" + data + " f=" + formattedData + " cnt=" + this.getRowCount();
};



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 초기 파라미터 선택값
    par_columnInfo.setValue("0");
    par_formatter.setValue("scwin.fmtMark");
};



// comp 생성
//  - MultiLine(레코드당 2 Line) 그리드 : header / gBody 각각 <w2:row> 2개
//      Line1 : sales(text/number,displayFormat) / detail(link) / grade(select, dlt_grade nodeset itemset)
//      Line2 : memo(textarea, colspan2) / region(text)
//  - Line 을 넘어 컬럼 인덱스가 이어짐 : sales=0, detail=1, grade=2, memo=3, region=4
//      → Line1 대상 인덱스(0/1/2) 와 Line2 대상 인덱스(3/4)는 서로 다른 고유값
//  - 모든 컬럼이 allow-list(text/link/select/textarea) 이므로 setCustomFormatter 동작
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_grade !== 'undefined') {
        $p.data.remove("dlt_grade");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] MultiLine(레코드당 2 Line) 그리드. Line1=sales(text/number displayFormat=#,##0,idx0)/detail(link,idx1)/grade(select,dlt_grade nodeset itemset,idx2), Line2=memo(textarea,colspan2,idx3)/region(text,idx4). Row 가 MultiLine 이어도 컬럼 인덱스는 Line 을 넘어 이어지는 고유값(0,1,2,3,4)을 가집니다. 모든 컬럼은 allow-list(text/link/select/textarea) 이므로 setCustomFormatter 가 동작합니다. 데이터 Row 3개.\n[절차] columnInfo(인덱스) 와 formatter(함수명) 선택 후 (setCustomFormatter 실행) 클릭 -> 해당 인덱스 Column 모든 Row 셀의 화면 표시값이 사용자 함수 반환값으로 바뀌는지 확인.\n[확인] Line1 대상 인덱스(0/1/2)와 Line2 대상 인덱스(3/4)가 서로 다른 고유 인덱스로 각각 지정되어, 선택한 인덱스의 Column 표시값만 포매터로 변형됨. fmtMark 는 formattedData+고유 idx 표기, fmtFull 은 4개 파라미터와 this.getRowCount() 로 this=GridView 를 확인."', '', 'label1');

    // select Column 의 itemset 용 DataList (코드/라벨) - value ref=code, label ref=label
    let strGrade = '';
    strGrade += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_grade" baseNode="list" repeatNode="map">';
    strGrade += '<w2:columnInfo>';
    strGrade += '<w2:column id="code" name="code" dataType="text"></w2:column>';
    strGrade += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strGrade += '</w2:columnInfo>';
    strGrade += '<w2:data use="true"></w2:data>';
    strGrade += '</w2:dataList>';
    $p.data.create(strGrade);
    dlt_grade.setJSON([
        { "code": "A", "label": "최우수" },
        { "code": "B", "label": "우수" },
        { "code": "C", "label": "보통" }
    ], false);

    // GridView 와 바인딩할 DataList 동적 생성 (각 Column 별 데이터)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="sales" name="sales" dataType="number"></w2:column>';
    strDlt += '<w2:column id="detail" name="detail" dataType="text"></w2:column>';
    strDlt += '<w2:column id="grade" name="grade" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "sales": "1250",  "detail": "상세보기", "grade": "A", "memo": "1차 검토 완료", "region": "서울" },
        { "sales": "30500", "detail": "상세보기", "grade": "B", "memo": "재검토 요청",   "region": "부산" },
        { "sales": "780",   "detail": "상세보기", "grade": "C", "memo": "신규 배정",     "region": "대구" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // itemset(nodeset) 공통 조각 (select 용) : label ref=label, value ref=code
    let itemset = '<w2:choices><w2:itemset nodeset="data:dlt_grade"><w2:label ref="label"></w2:label><w2:value ref="code"></w2:value></w2:itemset></w2:choices>';

    // target 생성 : MultiLine(레코드당 2 Line) - header / gBody 각각 <w2:row> 2개
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' defaultCellHeight="30" id="" style="width:100%;height:320px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setCustomFormatter (MultiLine) 테스트 그리드"></w2:caption>';
    // Header : Line1(sales/detail/grade) / Line2(memo/region)
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="120" inputType="text" id="h0" value="0:sales(text/number)"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="h1" value="1:detail(link)"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="h2" value="2:grade(select)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="210" colspan="2" inputType="text" id="h3" value="3:memo(textarea)"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="h4" value="4:region(text)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    // gBody : Line1(sales/detail/grade) / Line2(memo/region) → 레코드당 2 TR Line
    //  (중요) body 컬럼 id 는 dataList 컬럼 id 와 동일해야 셀에 데이터가 바인딩됨
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // idx0 sales (text/number, displayFormat="#,##0") -> formattedData 는 콤마 포맷값 전달 (allow)
    strTarget += '<w2:column width="120" inputType="text" dataType="number" displayFormat="#,##0" id="sales" dataList="sales"></w2:column>';
    // idx1 detail (link) (allow)
    strTarget += '<w2:column width="90" inputType="link" id="detail" dataList="detail"></w2:column>';
    // idx2 grade (select, dlt_grade nodeset itemset) (allow) - Line1
    strTarget += '<w2:column width="150" inputType="select" id="grade" dataList="grade">' + itemset + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    // idx3 memo (textarea, colspan2) (allow) - Line2
    strTarget += '<w2:column width="210" colspan="2" inputType="textarea" id="memo" dataList="memo"></w2:column>';
    // idx4 region (text) (allow) - Line2
    strTarget += '<w2:column width="150" inputType="text" id="region" dataList="region"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// [실행] setCustomFormatter : columnInfo(인덱스) 와 formatter(함수명) 으로 해당 Column 의 customFormatter 속성을 설정한다.
//  - MultiLine 이어도 각 Column 은 고유 인덱스를 가지므로, 선택한 인덱스(Line1: 0/1/2, Line2: 3/4)의 Column 만
//    표시값이 사용자 함수 반환값으로 변형/재렌더되는지 확인
//  - 모든 대상 컬럼이 allow-list(text/link/select/textarea) 이므로 setCustomFormatter 가 동작
scwin.btn_setCustomFormatter_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let formatter = par_formatter.getValue();
    let colID = target1.getColumnID(columnInfo);
    let cnt = dlt_bind.getRowCount();

    // setCustomFormatter 호출 (Column 단위, 고유 인덱스)
    target1.setCustomFormatter(columnInfo, formatter);

    // 적용된 해당 Column 의 모든 Row 화면 표시값 수집 (MultiLine 셀 td[id*='target1_cell_{row}_{columnIndex}'])
    let arr = [];
    for (let r = 0; r < cnt; r++) {
        let td = document.querySelector("td[id*='target1_cell_" + r + "_" + columnInfo + "']");
        arr.push(td ? td.textContent.trim() : '(td없음)');
    }

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setCustomFormatter(" + columnInfo + ", '" + formatter + "') [" + colID + "] -> 모든 Row 화면 표시값 : " + arr.join(' | '));
}
